<div class="nx-page-head"><div><div class="nx-kicker">GOLDENSITE / TRAZABILIDAD</div><h1>Cada acción tiene una historia.</h1><p>Eventos de acceso y administración con filtros y exportación. El registro no se borra desde esta pantalla.</p></div><?php if (\App\Core\IdentityAccess::allows('activity.export')): ?><a class="nx-btn" href="?<?= $e(http_build_query(array_merge($filters,['export'=>'csv']))) ?>">Exportar CSV</a><?php endif ?></div>
<section class="nx-panel"><form class="nx-panel-body nx-filter" method="get"><label>Buscar<input name="q" maxlength="100" value="<?= $e($filters['q']) ?>"></label><label>Evento<select name="event"><option value="">Todos</option><?php foreach ($events as $event): ?><option value="<?= $e($event['action']) ?>" <?= $filters['event']===$event['action']?'selected':'' ?>><?= $e($event['action']) ?></option><?php endforeach ?></select></label><label>Desde<input name="from" type="date" value="<?= $e($filters['from']) ?>"></label><label>Hasta<input name="to" type="date" value="<?= $e($filters['to']) ?>"></label><button class="nx-btn">Filtrar</button></form><div class="nx-table-wrap"><table class="nx-table"><thead><tr><th>Fecha</th><th>Cuenta</th><th>Evento</th><th>Descripción</th><th>Origen</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td class="nx-code"><?= $e($log['created_at']) ?><small>#<?= $log['id'] ?></small></td><td><?= $e($log['username']) ?></td><td><span class="nx-pill"><?= $e($log['action']) ?></span></td><td data-nx-content><?= $e($log['description']) ?></td><td class="nx-code"><?= $e($log['ip_address']) ?></td></tr><?php endforeach ?></tbody></table><?php if (!$logs): ?><p class="nx-empty">No hay resultados.</p><?php endif ?></div><div class="nx-table-foot"><span><?= $total ?> eventos · <?= $page ?></span><div class="nx-actions"><?php foreach ([$page-1=>'Anterior',$page+1=>'Siguiente'] as $p=>$label): if ($p<1||($p-1)*30>=$total) continue; ?><a class="nx-btn small" href="?<?= $e(http_build_query(array_merge($filters,['page'=>$p]))) ?>"><?= $label ?></a><?php endforeach ?></div></div></section>
